from math import inf as inf
from math import *
from collections import *
import sys
import os
input = sys.stdin.readline
for _ in range(int(input())):
	n = int(input())
	a = list(map(int, input().split()))
	b = [0] * 31
	fl = 'DRAW'
	for i in a:
		z = bin(i)[2:]
		z = z.zfill(31)
		for j in range(31):
			if z[j] == '1':
				b[j] += 1
	for i in b:
		if i % 2 == 0:
			continue
		if i % 4 == 3 and (n - i) % 2 == 0:
			fl = 'LOSE'
		else:
			fl = 'WIN'
		break
	print(fl)
